"""Add receipt/invoice projections and deferred material balance checks.

Legacy records remain authoritative. Tax, payments and accounting posting are outside scope.
"""
from alembic import op

revision = '0007_proc_fulfillment'
down_revision = '0006_proc_orders'
branch_labels = None
depends_on = None

SQL = "-- Material receipt/invoice projections. Tax, payment and accounting posting are outside this scope.\nCREATE TABLE public.proc_receipts (\n    tenant varchar(64) NOT NULL,\n    id varchar(64) NOT NULL,\n    source_revision integer NOT NULL CHECK(source_revision>=1),\n    order_id varchar(64) NOT NULL,\n    allocation_index integer NOT NULL CHECK(allocation_index>=0),\n    expected_order_revision integer NOT NULL CHECK(expected_order_revision>=1),\n    supplier_id varchar(64) NOT NULL,\n    sku varchar(80) NOT NULL,\n    accepted integer NOT NULL CHECK(accepted>=0),\n    rejected integer NOT NULL CHECK(rejected>=0),\n    quarantine integer NOT NULL CHECK(quarantine>=0),\n    evidence_id varchar(64) NOT NULL,\n    received_at timestamptz NOT NULL,\n    PRIMARY KEY(tenant,id),\n    CHECK(accepted::bigint+rejected+quarantine>0),\n    FOREIGN KEY(tenant,order_id,allocation_index)\n        REFERENCES public.proc_order_lines(tenant,order_id,line_index) DEFERRABLE INITIALLY DEFERRED\n);\nCREATE TABLE public.proc_invoices (\n    tenant varchar(64) NOT NULL,\n    id varchar(64) NOT NULL,\n    source_revision integer NOT NULL CHECK(source_revision>=1),\n    order_id varchar(64) NOT NULL,\n    allocation_index integer NOT NULL CHECK(allocation_index>=0),\n    expected_order_revision integer NOT NULL CHECK(expected_order_revision>=1),\n    supplier_id varchar(64) NOT NULL,\n    invoice_number varchar(100) NOT NULL CHECK(length(invoice_number)>0),\n    quantity integer NOT NULL CHECK(quantity>0),\n    unit_price numeric(14,2) NOT NULL CHECK(unit_price>0),\n    evidence_id varchar(64) NOT NULL,\n    status text NOT NULL CHECK(status IN ('matched','mismatch')),\n    tolerance text NOT NULL,\n    match_checks jsonb CHECK(jsonb_typeof(match_checks)='object'),\n    assessment_history jsonb NOT NULL CHECK(jsonb_typeof(assessment_history)='array'),\n    rechecked_by varchar(64),\n    recheck_reason text,\n    rechecked_at timestamptz,\n    PRIMARY KEY(tenant,id),\n    UNIQUE(tenant,supplier_id,invoice_number),\n    FOREIGN KEY(tenant,order_id,allocation_index)\n        REFERENCES public.proc_order_lines(tenant,order_id,line_index) DEFERRABLE INITIALLY DEFERRED\n);\nCREATE INDEX ix_proc_receipts_order_line ON public.proc_receipts(tenant,order_id,allocation_index);\nCREATE INDEX ix_proc_invoices_order_line ON public.proc_invoices(tenant,order_id,allocation_index,status);\nDO $$ DECLARE t text;\nBEGIN\n    FOREACH t IN ARRAY ARRAY['proc_receipts','proc_invoices'] LOOP\n        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);\n        EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);\n        EXECUTE format('CREATE POLICY tenant_scope ON public.%I TO supplypilot_app USING (tenant=NULLIF(current_setting(''supplypilot.tenant'',true),'''')) WITH CHECK (tenant=NULLIF(current_setting(''supplypilot.tenant'',true),''''))',t);\n        EXECUTE format('CREATE POLICY migration_owner ON public.%I TO supplypilot_migrator USING(true) WITH CHECK(true)',t);\n        EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC,supplypilot_app',t);\n        EXECUTE format('GRANT SELECT ON TABLE public.%I TO supplypilot_app',t);\n    END LOOP;\nEND $$;\n\nCREATE FUNCTION public.sync_procurement_fulfillment()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER\nSET search_path=pg_catalog,pg_temp\nAS $$ DECLARE d jsonb; amount numeric;\nBEGIN\n    IF TG_OP='UPDATE' AND\n       (OLD.kind IN ('receipt','invoice') OR NEW.kind IN ('receipt','invoice')) AND\n       (OLD.tenant,OLD.id,OLD.kind) IS DISTINCT FROM (NEW.tenant,NEW.id,NEW.kind) THEN\n        RAISE EXCEPTION 'Receipt/invoice identity, tenant and kind are immutable' USING ERRCODE='23514';\n    END IF;\n    IF TG_OP='UPDATE' AND OLD.kind IN ('receipt','invoice') AND\n       (OLD.data->>'order_id',OLD.data->>'allocation_index',OLD.data->>'supplier_id')\n       IS DISTINCT FROM (NEW.data->>'order_id',NEW.data->>'allocation_index',NEW.data->>'supplier_id') THEN\n        RAISE EXCEPTION 'Receipt/invoice order line and supplier are immutable' USING ERRCODE='23514';\n    END IF;\n    IF TG_OP='DELETE' THEN\n        IF OLD.kind='receipt' THEN DELETE FROM public.proc_receipts WHERE tenant=OLD.tenant AND id=OLD.id;\n        ELSIF OLD.kind='invoice' THEN DELETE FROM public.proc_invoices WHERE tenant=OLD.tenant AND id=OLD.id;\n        END IF;\n        RETURN OLD;\n    END IF;\n    d:=NEW.data::jsonb;\n    IF NEW.kind='receipt' THEN\n        INSERT INTO public.proc_receipts VALUES(NEW.tenant,NEW.id,NEW.revision,d->>'order_id',\n            (d->>'allocation_index')::integer,(d->>'expected_revision')::integer,d->>'supplier_id',\n            d->>'sku',(d->>'accepted')::integer,(d->>'rejected')::integer,(d->>'quarantine')::integer,\n            d->>'evidence_id',(d->>'at')::timestamptz)\n        ON CONFLICT(tenant,id) DO UPDATE SET source_revision=EXCLUDED.source_revision,\n            order_id=EXCLUDED.order_id,allocation_index=EXCLUDED.allocation_index,\n            expected_order_revision=EXCLUDED.expected_order_revision,supplier_id=EXCLUDED.supplier_id,\n            sku=EXCLUDED.sku,accepted=EXCLUDED.accepted,rejected=EXCLUDED.rejected,\n            quarantine=EXCLUDED.quarantine,evidence_id=EXCLUDED.evidence_id,received_at=EXCLUDED.received_at;\n    ELSIF NEW.kind='invoice' THEN\n        amount:=(d->>'unit_price')::numeric;\n        IF amount IS DISTINCT FROM round(amount,2) OR amount::text IN ('NaN','Infinity','-Infinity') THEN\n            RAISE EXCEPTION 'Invoice price must be finite with at most two decimal places' USING ERRCODE='23514';\n        END IF;\n        INSERT INTO public.proc_invoices VALUES(NEW.tenant,NEW.id,NEW.revision,d->>'order_id',\n            (d->>'allocation_index')::integer,(d->>'expected_revision')::integer,d->>'supplier_id',\n            d->>'invoice_number',(d->>'quantity')::integer,(d->>'unit_price')::numeric,\n            d->>'evidence_id',d->>'status',d->>'tolerance',d->'match_checks',\n            COALESCE(d->'assessment_history','[]'::jsonb),d->>'rechecked_by',d->>'recheck_reason',\n            (d->>'rechecked_at')::timestamptz)\n        ON CONFLICT(tenant,id) DO UPDATE SET source_revision=EXCLUDED.source_revision,\n            order_id=EXCLUDED.order_id,allocation_index=EXCLUDED.allocation_index,\n            expected_order_revision=EXCLUDED.expected_order_revision,supplier_id=EXCLUDED.supplier_id,\n            invoice_number=EXCLUDED.invoice_number,quantity=EXCLUDED.quantity,unit_price=EXCLUDED.unit_price,\n            evidence_id=EXCLUDED.evidence_id,status=EXCLUDED.status,tolerance=EXCLUDED.tolerance,\n            match_checks=EXCLUDED.match_checks,assessment_history=EXCLUDED.assessment_history,\n            rechecked_by=EXCLUDED.rechecked_by,recheck_reason=EXCLUDED.recheck_reason,rechecked_at=EXCLUDED.rechecked_at;\n    END IF;\n    RETURN NEW;\nEND $$;\nREVOKE ALL ON FUNCTION public.sync_procurement_fulfillment() FROM PUBLIC,supplypilot_app;\nCREATE TRIGGER records_fulfillment_sync AFTER INSERT OR UPDATE OR DELETE ON public.records\nFOR EACH ROW EXECUTE FUNCTION public.sync_procurement_fulfillment();\nUPDATE public.records SET data=data WHERE kind IN ('receipt','invoice');\n\n-- Validate the final transaction state: receive() inserts a receipt before updating the order.\nCREATE FUNCTION public.check_procurement_fulfillment()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER\nSET search_path=pg_catalog,pg_temp\nAS $$\nDECLARE t text; oid text; idx integer; line record; received_accepted bigint;\n        received_rejected bigint; received_quarantine bigint; matched_quantity bigint; order_state text;\nBEGIN\n    IF TG_OP='DELETE' THEN\n        t:=OLD.tenant;oid:=OLD.order_id;\n        IF TG_TABLE_NAME='proc_order_lines' THEN idx:=OLD.line_index;\n        ELSE idx:=OLD.allocation_index;END IF;\n    ELSE\n        t:=NEW.tenant;oid:=NEW.order_id;\n        IF TG_TABLE_NAME='proc_order_lines' THEN idx:=NEW.line_index;\n        ELSE idx:=NEW.allocation_index;END IF;\n    END IF;\n    -- Serialize matching checks for this order; lock survives until commit/rollback.\n    SELECT status INTO order_state FROM public.proc_orders WHERE tenant=t AND id=oid FOR UPDATE;\n    SELECT * INTO line FROM public.proc_order_lines WHERE tenant=t AND order_id=oid AND line_index=idx;\n    IF NOT FOUND THEN\n        IF EXISTS(SELECT 1 FROM public.proc_receipts WHERE tenant=t AND order_id=oid AND allocation_index=idx)\n           OR EXISTS(SELECT 1 FROM public.proc_invoices WHERE tenant=t AND order_id=oid AND allocation_index=idx) THEN\n            RAISE EXCEPTION 'Receipt/invoice references an unavailable order line' USING ERRCODE='23503';\n        END IF;\n        RETURN NULL;\n    END IF;\n    IF EXISTS(SELECT 1 FROM public.proc_receipts WHERE tenant=t AND order_id=oid AND allocation_index=idx\n              AND (supplier_id<>line.supplier_id OR sku<>line.sku))\n       OR EXISTS(SELECT 1 FROM public.proc_invoices WHERE tenant=t AND order_id=oid AND allocation_index=idx\n              AND supplier_id<>line.supplier_id) THEN\n        RAISE EXCEPTION 'Receipt/invoice supplier or SKU differs from order line' USING ERRCODE='23514';\n    END IF;\n    SELECT COALESCE(sum(accepted),0),COALESCE(sum(rejected),0),COALESCE(sum(quarantine),0)\n        INTO received_accepted,received_rejected,received_quarantine\n        FROM public.proc_receipts WHERE tenant=t AND order_id=oid AND allocation_index=idx;\n    IF (received_accepted,received_rejected,received_quarantine)\n       IS DISTINCT FROM (line.accepted::bigint,line.rejected::bigint,line.quarantine::bigint) THEN\n        RAISE EXCEPTION 'Receipt ledger differs from order disposition counters' USING ERRCODE='23514';\n    END IF;\n    SELECT COALESCE(sum(quantity),0) INTO matched_quantity FROM public.proc_invoices\n        WHERE tenant=t AND order_id=oid AND allocation_index=idx AND status='matched';\n    IF matched_quantity>line.accepted OR EXISTS(SELECT 1 FROM public.proc_invoices\n        WHERE tenant=t AND order_id=oid AND allocation_index=idx AND status='matched' AND unit_price<>line.unit_price) THEN\n        RAISE EXCEPTION 'Matched invoice exceeds accepted quantity or differs from approved price' USING ERRCODE='23514';\n    END IF;\n    IF order_state='closed' AND matched_quantity<>line.quantity THEN\n        RAISE EXCEPTION 'Closed order requires fully matched material invoices' USING ERRCODE='23514';\n    END IF;\n    RETURN NULL;\nEND $$;\nREVOKE ALL ON FUNCTION public.check_procurement_fulfillment() FROM PUBLIC,supplypilot_app;\nCREATE CONSTRAINT TRIGGER receipt_balance_check AFTER INSERT OR UPDATE OR DELETE ON public.proc_receipts\nDEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.check_procurement_fulfillment();\nCREATE CONSTRAINT TRIGGER invoice_balance_check AFTER INSERT OR UPDATE OR DELETE ON public.proc_invoices\nDEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.check_procurement_fulfillment();\nCREATE CONSTRAINT TRIGGER order_fulfillment_check AFTER INSERT OR UPDATE OR DELETE ON public.proc_order_lines\nDEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.check_procurement_fulfillment();\n-- Schedule checks for historical lines without altering their values.\nUPDATE public.proc_order_lines SET received=received;\n"


def upgrade():
    op.execute(SQL)


def downgrade():
    raise RuntimeError('Use the verified backup rollback procedure; automatic receipt/invoice projection removal is disabled.')
